"""Build a portable static knowledge library from the editorial JSON."""
from pathlib import Path
import json, html, shutil
import fitz
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public'
E=html.escape
talks=json.loads((ROOT/'data/talks.json').read_text(encoding='utf-8'))
for folder in ['assets','talks','data']: (OUT/folder).mkdir(parents=True,exist_ok=True)

def shell(title,body,prefix=''):
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Разбор 19 презентаций Большого Нарижника: применение, промты и предложения по навыкам Codex."><title>{E(title)} · Нарижник / Практика</title><link rel="icon" href="data:,"><link rel="stylesheet" href="{prefix}assets/style.css"></head><body><a class="skip" href="#main">Перейти к содержимому</a><header class="top"><a class="brand" href="{prefix}index.html"><span class="mark">Н/П</span> НАРИЖНИК <span class="brand-light">/ ПРАКТИКА</span></a><nav aria-label="Главная навигация"><a href="{prefix}index.html">Доклады</a><a href="{prefix}skills.html">Идеи навыков</a><a href="{prefix}summary.html">Краткий обзор</a></nav></header><main id="main">{body}</main><footer><strong>Нарижник / Практика</strong><p>Авторские разборы по материалам 19 PDF. Подготовлено 16 ноября 2026. Тезисы докладов и наши предложения обозначены отдельно. Это независимый рабочий каталог.</p><a href="{prefix}methodology.html">Методика и ограничения</a> · <a href="https://drive.google.com/drive/folders/1FkTsSb_QiNAhWrNJwLh0Cs6jkkwXcPmn" target="_blank" rel="noopener">Папка оригиналов ↗</a></footer><script src="{prefix}assets/app.js" defer></script></body></html>'''

def ul(items):return '<ul>'+''.join(f'<li>{E(x)}</li>' for x in items)+'</ul>'
def ol(items):return '<ol>'+''.join(f'<li>{E(x)}</li>' for x in items)+'</ol>'
def save(name,text):(OUT/name).write_text(text,encoding='utf-8')
def card(t,i):
    hay=E(' '.join([t['title'],t['author'],t['topic'],t['summary'],t['skill']['name']]),quote=True)
    return f'''<article class="card" data-search="{hay}" data-topic="{E(t['topic'])}"><a class="cover" tabindex="-1" aria-hidden="true" href="talks/{t['slug']}.html"><img src="assets/{t['slug']}.webp" loading="lazy" width="640" height="360" alt=""></a><div class="card-body"><div class="overline">{E(t['topic'])} <span>/{i:02}</span></div><h3><a href="talks/{t['slug']}.html">{E(t['title'])}</a></h3><p class="author">{E(t['author'])} · {t['pages']} стр.</p><p>{E(t['summary'])}</p><div class="card-bottom"><span class="chip">{t['skill']['priority']} · идея навыка</span><a class="arrow" href="talks/{t['slug']}.html" aria-label="Разобрать: {E(t['title'])}">Разбор →</a></div></div></article>'''

total_pages=sum(t['pages'] for t in talks)
intro=f'''<section class="hero"><div class="eyebrow">БОЛЬШОЙ НАРИЖНИК · БАЗА ЗНАНИЙ</div><h1>Из докладов —<br><em>в рабочие процессы.</em></h1><p class="lead">Что взять в работу из каждой презентации: короткий разбор, конкретные шаги, промт и идея навыка для Codex.</p><div class="hero-actions"><a class="button" href="#library">Выбрать доклад <span>↓</span></a><a class="text-link" href="skills.html">Что разработать первым →</a></div><div class="stats"><div><b>19</b><span>разобранных PDF</span></div><div><b>{total_pages}</b><span>страниц в корпусе</span></div><div><b>19</b><span>прикладных промтов</span></div><div><b>19</b><span>предложений навыков</span></div></div></section><section class="section" id="library"><div class="section-head"><div><div class="eyebrow">БИБЛИОТЕКА</div><h2>Найдите свою задачу</h2></div><a href="summary.html">Все выводы на одной странице →</a></div><div class="filters"><label>Поиск по теме, автору или задаче<input id="search" type="search" placeholder="Например: миграция, GEO, Шакин"></label><label>Направление<select id="topic"><option value="">Все направления</option>{''.join(f'<option>{E(x)}</option>' for x in sorted({t['topic'] for t in talks}))}</select></label><button id="reset" class="secondary" type="button">Сбросить</button></div><p id="result-count" class="muted" role="status">19 докладов</p><p id="empty" hidden>Ничего не найдено. Измените запрос или сбросьте фильтры.</p><div class="grid">{''.join(card(t,i) for i,t in enumerate(talks,1))}</div></section>'''
intro=intro.replace('<select id="topic">','<select id="topic" aria-label="Направление">')
save('index.html',shell('Библиотека докладов',intro))

for t in talks:
    slug=t['slug'];s=t['skill']
    with fitz.open(ROOT/'sources'/t['filename']) as doc:
        pix=doc[0].get_pixmap(matrix=fitz.Matrix(1,1))
        from PIL import Image
        im=Image.frombytes('RGB',[pix.width,pix.height],pix.samples)
        im.thumbnail((800,450));im.save(OUT/'assets'/f'{slug}.webp','WEBP',quality=78)
    notes=''.join(f'<li><span>{E(x["text"])}</span><a class="source" href="{E(t["source_url"])}" target="_blank" rel="noopener">PDF, стр. {x["page"]} ↗</a></li>' for x in t['lessons'])
    body=f'''<section class="talk-head"><a class="back" href="../index.html#library">← Все доклады</a><div class="eyebrow">{E(t['topic'])} · {t['pages']} СТРАНИЦ</div><h1>{E(t['title'])}</h1><p class="lead">{E(t['author'])}</p><a class="button small" href="{E(t['source_url'])}" target="_blank" rel="noopener">Открыть оригинал PDF ↗</a></section><div class="talk-layout"><aside><img class="talk-cover" src="../assets/{slug}.webp" width="640" height="360" alt="Обложка презентации {E(t['author'])}"><nav aria-label="Разделы доклада"><a href="#summary">Коротко</a><a href="#source">Что в презентации</a><a href="#practice">Как применить</a><a href="#technical">Технический сценарий</a><a href="#prompt">Готовый промт</a><a href="#skill">Идея навыка</a><a href="#limits">Ограничения</a></nav></aside><article class="reading"><section id="summary"><div class="eyebrow">РЕДАКЦИОННОЕ САММАРИ</div><h2>О чём доклад</h2><p>{E(t['summary'])}</p></section><section id="source"><h2>Что взять из презентации</h2><ul class="evidence">{notes}</ul></section><section id="practice"><div class="eyebrow">НАША АДАПТАЦИЯ ДЛЯ ПРАКТИКИ</div><h2>Как использовать в проекте</h2><h3>Что подготовить</h3><p>{E(t['inputs'])}</p><h3>Последовательность</h3>{ol(t['steps'])}</section><section id="technical"><h2>Технический сценарий</h2><p>{E(t['technical'])}</p></section><section id="prompt"><div class="section-head"><h2>Промт для работы</h2><button type="button" class="secondary copy" data-copy="prompt-text">Скопировать</button></div><p class="muted">Добавьте свои файлы и контекст задачи. Промт подготовлен для этого каталога.</p><div class="prompt" id="prompt-text">{E(t['prompt'])}</div><p class="copy-status" role="status"></p></section><section class="skill-box" id="skill"><div class="eyebrow">ПРЕДЛОЖЕНИЕ · {s['priority']}</div><h2>{E(s['name'])}</h2><p>{E(s['scope'])}</p><h3>Связь с установленными навыками</h3><p>{E(s['overlap'])}</p><p class="muted">Это спецификация идеи. Навык ещё не реализован и не установлен.</p></section><section id="limits" class="caution"><h2>Что учитывать</h2><p>{E(t['caution'])}</p><p class="muted">Разбор основан на PDF. Устные объяснения и материалы за QR-кодами не входят в прочитанный корпус. OCR применён к {t['ocr_pages']} страницам; графики не использованы для восстановления неразборчивых цифр.</p></section><p><a href="../skills.html">Перейти к плану разработки навыков →</a></p></article></div>'''
    save(f'talks/{slug}.html',shell(t['title'],body,'../'))

rows=''.join(f'<tr><td><a href="talks/{t["slug"]}.html">{E(t["author"])}</a></td><td><strong>{E(t["skill"]["name"])}</strong><p>{E(t["skill"]["scope"])}</p></td><td><span class="chip">{t["skill"]["priority"]}</span></td><td>{E(t["skill"]["overlap"])}</td></tr>' for t in sorted(talks,key=lambda t:t['skill']['priority']))
roadmap='''<section class="section compact"><div class="eyebrow">ПЛАН РАЗВИТИЯ · НАША ОЦЕНКА</div><h1>Какие навыки делать первыми</h1><p class="lead">19 предложений по докладам сведены в общий план. Повторяющиеся задачи лучше объединить, а готовые навыки — расширить.</p><div class="roadmap"><div class="panel"><span class="chip">Этап 1 · 6–10 часов</span><h2>Сверка выгрузок</h2><p>Один чистый CSV, правила объединения, реестр потерь и контрольные суммы. Основа всех последующих отчётов.</p></div><div class="panel"><span class="chip">Этап 2 · 8–16 часов</span><h2>Миграция домена</h2><p>Карта URL, HTTP-цепочки, canonical, индексируемость и итоговая таблица ошибок. Результат легко проверить.</p></div><div class="panel"><span class="chip">Этап 3 · 16–24 часа</span><h2>Бизнес-аналитика SEO</h2><p>Недельные сегменты, контроль полноты, журнал релизов, спрос и сезонность. Нужны реальные выгрузки.</p></div><div class="panel"><span class="chip">Этап 4 · 16–32 часа</span><h2>Мониторинг GEO</h2><p>Для MVP — импорт готовых ответов, повторные замеры и разметка брендов. Автосбор ответов — отдельная интеграция.</p></div></div><p class="muted">Оценки для прототипов на известных форматах данных; интеграции, доступы, сопровождение и платные API оцениваются отдельно. P1 — первый приоритет, P2 — следующий, P3 — по отдельной потребности.</p><h2>Что расширить в текущем наборе</h2><ul><li><strong>triplet-article-writer:</strong> карточки фактов, матрица интентов и проверки полноты.</li><li><strong>drmax-seo:</strong> карта кластеров и URL, сегментная аналитика.</li><li><strong>vk-community-manager:</strong> проверка оформления и контентные эксперименты.</li><li><strong>product-marketing-context:</strong> чекап маркетинга, медиапортфель, спикерские материалы.</li></ul><h2>Все предложения по докладам</h2><div class="table-wrap"><table><thead><tr><th>Источник</th><th>Предложение</th><th>Приоритет</th><th>Как встроить</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><p><a href="data/talks.json" download>Скачать все разборы в JSON ↓</a></p><p>На этом этапе сформулированы предложения и технические сценарии. Новые навыки в Codex не устанавливались.</p></section>'''
save('skills.html',shell('План навыков',roadmap))
summary='''<section class="section compact"><div class="eyebrow">ОБЗОР ДЛЯ БЫСТРОГО ЧТЕНИЯ</div><h1>19 докладов.<br>Что взять в работу.</h1><p class="lead">Начните с своей задачи: диагностики, контента, видимости в ИИ или продвижения эксперта. Для деталей у каждого материала есть отдельная страница.</p><div class="panel"><h2>Как пользоваться</h2><ol><li>Выберите доклад по задаче или направлению.</li><li>Подготовьте указанные входные данные.</li><li>Возьмите промт и выполните небольшой пробный сценарий.</li><li>Проверьте результат по источникам и контрольным примерам.</li><li>Повторяемый процесс оформите в навык после проверки на своих данных.</li></ol></div>'''
for i,t in enumerate(talks,1): summary+=f'<section class="summary-item"><div class="eyebrow">{i:02} / {E(t["topic"])}</div><h2><a href="talks/{t["slug"]}.html">{E(t["author"])} — {E(t["title"])}</a></h2><p>{E(t["summary"])}</p><p><strong>С чего начать:</strong> {E(t["steps"][0])}</p><p><strong>Идея навыка:</strong> {E(t["skill"]["name"])} · {t["skill"]["priority"]}</p></section>'
save('summary.html',shell('Краткое саммари всех докладов',summary+'</section>'))
save('methodology.html',shell('Методика',f'''<section class="section compact"><div class="eyebrow">ИСТОЧНИКИ И ГРАНИЦЫ</div><h1>Как подготовлены разборы</h1><p>Получены 19 PDF из общей папки Google Drive: {total_pages} страниц. Сохранены оригинальные имена, идентификаторы, размер и SHA-256. Текст извлечён по страницам локально через PyMuPDF; для страниц с недостаточным текстовым слоем использован Tesseract с русским и английским языками.</p><h2>Что является источником</h2><p>Блок «Что взять из презентации» ссылается на страницы конкретного PDF. Ссылки ведут к оригиналу в Drive, а номер страницы указан рядом. Оригиналы остаются на стороне владельцев; в публичном репозитории опубликованы наши разборы, а не полные PDF и распознанные тексты.</p><h2>Что подготовлено для каталога</h2><p>Шаги применения, технические сценарии, промты, названия и приоритеты навыков — наши предложения на основе прочитанного. Они не являются цитатами спикеров. Тексты и смысловой анализ выполнены Codex; массовые вызовы сторонних LLM не использовались.</p><h2>Проверка спорных тезисов</h2><p>Доклады отражают взгляды и срезы данных авторов. В каталоге отмечены различия между корреляцией и причинностью, частотой и трафиком, трёхсловными сочетаниями и фактическими триплетами. Чужие кейсы, проценты охватов, зарплаты и доходы не представлены как обещания.</p><h2>Ограничения</h2><p>Записи выступлений и документы по QR-кодам не изучены. OCR может ошибаться в мелких диаграммах и декоративных слайдах; сомнительные числа не использованы для новых расчётов. Действующие правила поисковиков, соцсетей, тарифы и API перед внедрением нужно проверить заново. Полная независимая проверка всех исследований, упомянутых спикерами, не проводилась.</p><h2>Артефакты</h2><p><a href="data/talks.json" download>Редакционные карточки JSON ↓</a> · <a href="data/sources.json" download>Реестр исходных файлов ↓</a></p></section>'''))
for name in ['talks.json','sources.json']:shutil.copyfile(ROOT/'data'/name,OUT/'data'/name)
save('.nojekyll','')
print(f'Built {len(talks)} talk pages; corpus {total_pages} pages')
